tool_input.new_string:
// MCPServerConfig defines how to invoke an MCP server -- either a local
// stdio subprocess (Command/Args, the original and still the common shape)
// or a remote HTTP server (Type/URL/Headers). omitempty on every field
// after Command/Args means an existing stdio entry marshals exactly as it
// always has: Command/Args were never empty for those entries, so their
// presence in the output is unaffected, while Type/URL/Headers simply never
// appear. An http entry is the mirror image: Command and Args stay their
// zero values and are omitted, leaving only Type/URL/Headers.
type MCPServerConfig struct {
	Command string            `json:"command,omitempty"`
	Args    []string          `json:"args,omitempty"`
	Type    string            `json:"type,omitempty"`
	URL     string            `json:"url,omitempty"`
	Headers map[string]string `json:"headers,omitempty"`
}

// DefaultMCPRegistry returns the built-in server registry. context7's
// Headers value is a literal "${CONTEXT7_API_KEY}" placeholder, not the
// key itself -- Claude Code expands ${VAR} references in mcp-config
// against the worker subprocess's own environment at spawn time, and
// ClaudeRunner.Run (runner.go) is what actually puts CONTEXT7_API_KEY into
// that environment, by resolving it from cmd.EnvVars (the declared env-var
// allowlist) via resolveEnvVars. No secret value is ever written into this
// registry, a generated mcp-config file, or a log line.
func DefaultMCPRegistry() map[string]MCPServerConfig {
	return map[string]MCPServerConfig{
		"ethos":        {Command: "ethos", Args: []string{"mcp"}},
		"beadle-email": {Command: "beadle-email", Args: []string{"serve"}},
		"biff":         {Command: "biff", Args: []string{"mcp"}},
		"context7": {
			Type: "http",
			URL:  "https://mcp.context7.com/mcp",
			Headers: map[string]string{
				"CONTEXT7_API_KEY": "${CONTEXT7_API_KEY}",
			},
		},
	}
}

tool_input.old_string:
// MCPServerConfig defines how to invoke an MCP server.
type MCPServerConfig struct {
	Command string   `json:"command"`
	Args    []string `json:"args"`
}

// DefaultMCPRegistry returns the built-in server registry.
func DefaultMCPRegistry() map[string]MCPServerConfig {
	return map[string]MCPServerConfig{
		"ethos":        {Command: "ethos", Args: []string{"mcp"}},
		"beadle-email": {Command: "beadle-email", Args: []string{"serve"}},
		"biff":         {Command: "biff", Args: []string{"mcp"}},
	}
}

tool_input.new_string:
func TestDefaultMCPRegistry(t *testing.T) {
	reg := DefaultMCPRegistry()
	assert.Len(t, reg, 4)
	assert.Contains(t, reg, "ethos")
	assert.Contains(t, reg, "beadle-email")
	assert.Contains(t, reg, "biff")
	assert.Contains(t, reg, "context7")
}

// TestBuildMCPConfig_StdioEmissionByteIdentical proves that adding the
// Type/URL/Headers fields to MCPServerConfig did not change one byte of
// what a stdio server already emitted -- omitempty on the new fields (and
// on Command/Args, unaffected here since both are always non-zero for a
// stdio entry) means only "command" and "args" ever appear. Claude Code
// parses this file to spawn workers; a shape change here breaks worker
// spawning in a way that would not look like an MCP problem.
func TestBuildMCPConfig_StdioEmissionByteIdentical(t *testing.T) {
	registry := DefaultMCPRegistry()
	tmpDir := t.TempDir()
	tmpl := &MissionTemplate{TmpDir: tmpDir}

	path, err := tmpl.BuildMCPConfig([]string{"ethos"}, registry)
	require.NoError(t, err)
	defer os.Remove(path)

	data, err := os.ReadFile(path)
	require.NoError(t, err)

	var doc struct {
		MCPServers map[string]json.RawMessage `json:"mcpServers"`
	}
	require.NoError(t, json.Unmarshal(data, &doc))

	assert.JSONEq(t, `{"command":"ethos","args":["mcp"]}`, string(doc.MCPServers["ethos"]))
}

// TestBuildMCPConfig_HTTPServerEmission proves the http shape: only
// type/url/headers appear, never command/args.
func TestBuildMCPConfig_HTTPServerEmission(t *testing.T) {
	registry := DefaultMCPRegistry()
	tmpDir := t.TempDir()
	tmpl := &MissionTemplate{TmpDir: tmpDir}

	path, err := tmpl.BuildMCPConfig([]string{"context7"}, registry)
	require.NoError(t, err)
	defer os.Remove(path)

	data, err := os.ReadFile(path)
	require.NoError(t, err)

	var doc struct {
		MCPServers map[string]json.RawMessage `json:"mcpServers"`
	}
	require.NoError(t, json.Unmarshal(data, &doc))

	assert.JSONEq(t,
		`{"type":"http","url":"https://mcp.context7.com/mcp","headers":{"CONTEXT7_API_KEY":"${CONTEXT7_API_KEY}"}}`,
		string(doc.MCPServers["context7"]))
	assert.NotContains(t, string(doc.MCPServers["context7"]), `"command"`)
	assert.NotContains(t, string(doc.MCPServers["context7"]), `"args"`)
}
